entries[22557] = { ["name"] = "Formel: Waffe - Meister des Kampfes", ["text"] = "Benötigt Verzauberkunst (360)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, manchmal nahe Gruppenmitglieder um 180 bis 300 geheilt werden, wenn ein Nahkampfangriff durchgeführt wird. Erfordert einen Gegenstand der Stufe 35 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass sie manchmal nahe Gruppenmitglieder um 180 bis 300 heilt, wenn ein Nahkampfangriff durchgeführt wird. Erfordert einen Gegenstand der Stufe 35 oder höher.\nVerkaufspreis:" }
entries[22558] = { ["name"] = "Formel: Waffe - Zauberflut", ["text"] = "Benötigt Verzauberkunst (360)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass Eure Zauber manchmal bei allen Gruppenmitgliedern in der Nähe 100 Mana wiederherstellen. Erfordert einen Gegenstand der Stufe 35 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass beim Zauberwirken manchmal bei nahen Gruppenmitgliedern 100 Mana wiederhergestellt werden. Benötigt einen Gegenstand der Stufe 35 oder höher.\nVerkaufspreis:" }
entries[22559] = { ["name"] = "Formel: Waffe - Mungo", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (375)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass manchmal die Beweglichkeit um 120 und geringfügig das Angriffstempo erhöht wird. Erfordert einen Gegenstand der Stufe 35 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass eine Chance besteht, die Beweglichkeit um 120 und das Angriffstempo geringfügig zu erhöhen. Erfordert einen Gegenstand der Stufe 35 oder höher.\nVerkaufspreis:" }
entries[22560] = { ["name"] = "Formel: Waffe - Sonnenfeuer", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (375)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass die Feuer- und Arkanzaubermacht um 50 erhöht wird. Erfordert einen Gegenstand der Stufe 35 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass die Feuer- und Arkanzaubermacht um 50 erhöht wird. Erfordert einen Gegenstand der Stufe 35 oder höher.\nVerkaufspreis:" }
entries[22561] = { ["name"] = "Formel: Waffe - Seelenfrost", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (375)\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass die Frost- und Schattenzaubermacht um 54 erhöht wird. Erfordert einen Gegenstand der Stufe 35 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass die Schatten- und Frostzaubermacht um 54 erhöht wird. Erfordert einen Gegenstand der Stufe 35 oder höher.\nVerkaufspreis:" }
entries[22562] = { ["name"] = "Formel: Überragendes Manaöl", ["text"] = "Benötigt Verzauberkunst (310)\nBenutzen: Lehrt Euch die Herstellung von überragendem Manaöl.\nErstellt Überragendes Manaöl.\nVerkaufspreis:\nÜberragendes Manaöl\nBenötigt Stufe 52\nBenutzen: Trägt überragendes Manaöl auf Eure Waffe auf, das Eure Willenskraft um 25 erhöht. Hält 1 Stunde lang an. Kann nicht auf Gegenstände über Stufe 200 angewandt werden.\n5 Aufladungen\nVerkaufspreis:\nBenötigt Arkaner Staub (3), Netherblüte , Kristallphiole" }
entries[22563] = { ["name"] = "Formel: Überragendes Zauberöl", ["text"] = "Benötigt Verzauberkunst (340)\nBenutzen: Lehrt Euch die Herstellung von überragendem Zauberöl.\nErstellt Überragendes Zauberöl.\nVerkaufspreis:\nÜberragendes Zauberöl\nBenötigt Stufe 58\nBenutzen: Trägt überragendes Zauberöl auf Eure Waffe auf, das Eure Intelligenz um 40 erhöht. Hält 1 Stunde lang an. Kann nicht auf Gegenstände über Stufe 200 angewandt werden.\n5 Aufladungen\nVerkaufspreis:\nBenötigt Arkaner Staub (3), Alptraumranke , Kristallphiole" }
entries[22564] = { ["name"] = "Formel: Arkaner Staub", ["text"] = "Benötigt Verzauberkunst (325)\nBenutzen: Lehrt Euch, einen arkanen Kristall in arkanen Staub umzuwandeln.\nWandelt einen Arkankristall in arkanen Staub um.\nVerkaufspreis:\nArkaner Staub\nBenötigt Arkankristall" }
entries[22565] = { ["name"] = "Formel: Großer Prismasplitter", ["text"] = "Benötigt Verzauberkunst (335)\nBenutzen: Lehrt Euch, kleine Prismasplitter in einen großen Prismasplitter umzuwandeln.\nWandelt drei kleine Prismasplitter in einen großen Prismasplitter um.\nVerkaufspreis:\nGroßer Prismasplitter\nBenötigt Kleiner Prismasplitter (3)" }
